package com.yeyamo_mobile.api.support_service.infrastructure.web;
import java.nio.charset.StandardCharsets;import java.util.*;import javax.crypto.spec.SecretKeySpec;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.core.convert.converter.Converter;import org.springframework.security.authentication.AbstractAuthenticationToken;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.core.*;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.security.web.SecurityFilterChain;
@Configuration public class SecurityConfig {
 @Bean SecurityFilterChain security(HttpSecurity http,JwtAuthorities converter)throws Exception{return http.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/actuator/health/**","/v3/api-docs/**","/swagger-ui/**").permitAll().requestMatchers("/api/v1/admin/support/**").hasAnyRole("SUPPORT","ADMIN","SUPER_ADMIN").anyRequest().denyAll()).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(converter))).build();}
 @Bean JwtDecoder decoder(@Value("${jwt.secret}")String secret){if(secret==null||secret.getBytes(StandardCharsets.UTF_8).length<32)throw new IllegalArgumentException("JWT_SECRET must contain at least 32 bytes");return NimbusJwtDecoder.withSecretKey(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256")).build();}
 @Bean JwtAuthorities authorities(){return new JwtAuthorities();}
 static final class JwtAuthorities implements Converter<Jwt,AbstractAuthenticationToken>{public AbstractAuthenticationToken convert(Jwt jwt){Set<String> values=new HashSet<>();List<String> roles=jwt.getClaimAsStringList("roles");if(roles!=null)roles.forEach(r->values.add(r.startsWith("ROLE_")?r:"ROLE_"+r));String role=jwt.getClaimAsString("role");if(role!=null)values.add(role.startsWith("ROLE_")?role:"ROLE_"+role);return new JwtAuthenticationToken(jwt,values.stream().map(SimpleGrantedAuthority::new).map(GrantedAuthority.class::cast).toList(),jwt.getSubject());}}
}
